            aOrbiterA = ((aWandererA + RotL64(aPrevious, 47U)) + 0x9E8E3CB39BB74C8DULL) + aOASaltA[(((511U - aIndex) + 409U)) & S_SALT1];
            aOrbiterD = ((aWandererB + RotL64(aScatter, 60U)) + RotL64(aCarry, 13U)) + 0x16485CC8F0DB5BB8ULL;
            aOrbiterJ = ((aWandererF + RotL64(aCross, 27U)) + 0xCD0B5CC36EC3D7BAULL) + aOASaltE[(((511U - aIndex) + 169U)) & S_SALT1];
            aOrbiterC = ((aWandererH + RotL64(aScatter, 19U)) + 0x1BB027F46EBC3734ULL) + aOASaltD[((aIndex + 268U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xEC3EE0D6587EBB3DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x42A8E4AD56ABCD78ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD1AE5831DEE5E795ULL), 39U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xEB83B4E9AD06BBB5ULL;
