            aOrbiterB = (aWandererF + RotL64(aCross, 29U)) + 0xC5BC7A9E791CD96CULL;
            aOrbiterG = (aWandererD + RotL64(aScatter, 3U)) + 0x19C205A2F8D64F47ULL;
            aOrbiterH = ((aWandererB + RotL64(aIngress, 23U)) + RotL64(aCarry, 47U)) + 0x9E0F9E5E50D66C09ULL;
