            aOrbiterI = ((aWandererK + RotL64(aScatter, 40U)) + 0x56BCFBD626C80958ULL) + aOASaltG[((aIndex + 211U)) & S_SALT1];
            aOrbiterD = (((aWandererG + RotL64(aPrevious, 35U)) + RotL64(aCarry, 3U)) + 0x841FDB47A50CAC97ULL) + aOASaltA[((aIndex + 437U)) & S_SALT1];
