            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xD7731E577D488EEAULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x7B7C70A23C1B55A2ULL) ^ aOUSaltB[((aIndex + 142U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xE488CBEB8B3BDD69ULL), 43U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0xAC89A975670B5811ULL) + aOUSaltH[(((511U - aIndex) + 95U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x341C75EAACF932CFULL;
            aOrbiterK = RotL64((aOrbiterK * 0x76E464F83C631E45ULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x96E5A0BE5811FA64ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x5F69A1D1D447F578ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x61A7DCA4239F14A9ULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x9A20D14B39553FB6ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0xD4D51E103CAA677DULL;
            aOrbiterB = RotL64((aOrbiterB * 0x3DD7ECD28A9E7C2FULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x62A72EB49CFBCEF7ULL) + aOUSaltC[(((511U - aIndex) + 254U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xF0A9E706F74C7ED2ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x920C78FE7DDAC883ULL), 29U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x3B282C39C29E1975ULL) + aOUSaltE[((aIndex + 30U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0xB144B9347A0A6D3EULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA544AAB3F7A27CB1ULL), 11U);
