            aWandererI = aWandererI ^ ((RotL64(aScatter, 46U) + aOrbiterE) + RotL64(aOrbiterB, 5U));
            aWandererG = aWandererG + ((RotL64(aIngress, 57U) + aOrbiterA) + RotL64(aOrbiterE, 23U));
            //
            aCarry = aCarry + (RotL64(aWandererF, 27U) ^ aWandererK);
            aCarry = aCarry + (RotL64(aWandererJ, 20U) ^ aWandererD);
            aCarry = aCarry + (RotL64(aWandererG, 23U) ^ aWandererH);
            aCarry = aCarry + (RotL64(aWandererB, 41U) ^ aWandererA);
            aCarry = aCarry + RotL64(aWandererI, 47U);
            aCarry = aCarry + RotL64(aIngress, 5U);
