            aOrbiterF = ((aWandererJ + RotL64(aIngress, 26U)) + 0xE21D6C5750924A08ULL) + aOASaltH[(((511U - aIndex) + 504U)) & S_SALT1];
            aOrbiterB = ((aWandererD + RotL64(aScatter, 3U)) + 0x67244E598110D0BEULL) + aOASaltA[(((511U - aIndex) + 296U)) & S_SALT1];
