            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xBC04EBAD4443BF75ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0xDA6693741322F507ULL) ^ aOUSaltH[(((511U - aIndex) + 511U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x5929138484B94B61ULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x4941A3D293581BA5ULL;
