            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x6AE8AF1B62995DF2ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x63E9107F6AF1DC31ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x1FA4E6048D903CE3ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0xF1A069FDB8A5D713ULL) ^ aOUSaltF[((aIndex + 449U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x5CBA36296D0F440BULL), 27U);
