            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x61DE4854E9DADAE0ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0xAF0DA59B14E1AB12ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD2D5D98F3B7186D7ULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xBE908514AF468E9CULL;
