            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x11B8C4E244AF9581ULL) + aOUSaltB[((aIndex + 253U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x70CE67DE0DA2CB4AULL;
