            aWandererD = aWandererD ^ ((RotL64(aIngress, 44U) + RotL64(aOrbiterC, 60U)) + aOrbiterE);
            aWandererG = aWandererG + (((RotL64(aCross, 27U) + aOrbiterD) + RotL64(aOrbiterH, 3U)) + RotL64(aCarry, 5U));
