            aWandererC = aWandererC + ((RotL64(aScatter, 41U) + aOrbiterE) + RotL64(aOrbiterH, 21U));
            aWandererJ = aWandererJ ^ (((RotL64(aCross, 39U) + aOrbiterF) + RotL64(aOrbiterA, 5U)) + aWUSaltB[((aIndex + 405U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aPrevious, 13U) + RotL64(aOrbiterI, 57U)) + aOrbiterH) + aWUSaltD[(((511U - aIndex) + 299U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aIngress, 53U) + aOrbiterF) + RotL64(aOrbiterI, 14U));
            //
            aCarry = aCarry + (RotL64(aWandererJ, 60U) ^ aWandererF);
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererE, 43U));
            aCarry = aCarry + (aWandererD ^ RotL64(aWandererK, 41U));
            aCarry = aCarry + (RotL64(aWandererG, 21U) ^ aWandererI);
            aCarry = aCarry + (RotL64(aWandererH, 10U) ^ aWandererB);
            aCarry = aCarry + RotL64(aWandererA, 19U);
