            aOrbiterF = ((aWandererD + RotL64(aPrevious, 44U)) + 0xB8A197DF808160F6ULL) + aOASaltD[((aIndex + 495U)) & S_SALT1];
            aOrbiterE = (aWandererC + RotL64(aScatter, 51U)) + 0xDFDCF14D8476EF60ULL;
